   142	/// Fold the daemon's global request/permission snapshots into a compact,
   143	/// truthful activity projection. Permissions replace their matching waiting
   144	/// request, terminal success/cancellation is omitted, and stale failure noise is
   145	/// bounded to the newest three authoritative errored requests.
   146	pub(crate) fn derive_attention_items(
   147	    requests: &[RequestSnapshot],
   148	    permissions: &[PermissionSnapshot],
   149	    sessions: &[IslandSession],
   150	) -> Vec<IslandAttentionItem> {
   151	    let permission_requests: HashSet<&str> = permissions
   152	        .iter()
   153	        .map(|permission| permission.request_id.as_str())
   154	        .collect();
   155	    let mut items = Vec::new();
   156	
   157	    for permission in permissions {
   158	        let (session_title, project) =
   159	            session_attention_metadata(sessions, permission.session_id.as_deref());
   160	        let tool = (!permission.tool.trim().is_empty()).then(|| permission.tool.trim().to_string());
   161	        let detail = if !permission.reason.trim().is_empty() {
   162	            bounded_detail(&permission.reason)
   163	        } else if let Some(tool) = tool.as_deref() {
   164	            format!("Review requested access for {tool}")
   165	        } else {
   166	            "Review requested access".to_string()
   167	        };
   168	        items.push(IslandAttentionItem {
   169	            id: format!("permission:{}", permission.permission_id),
   170	            request_id: permission.request_id.clone(),
   171	            permission_id: Some(permission.permission_id.clone()),
   172	            session_id: permission.session_id.clone(),
   173	            session_title,
   174	            project,
   175	            tool,
   176	            detail,
   177	            updated_at: permission.created_at.clone(),
   178	            state: IslandAttentionState::NeedsHuman,
   179	        });
   180	    }
   181	
   182	    let mut ordered_requests = requests.iter().collect::<Vec<_>>();
   183	    ordered_requests.sort_by(|a, b| {
   184	        request_updated_at(b)
   185	            .cmp(&request_updated_at(a))
   186	            .then_with(|| a.request_id.cmp(&b.request_id))
   187	    });
   188	    let mut failed_count = 0usize;
   189	    for request in ordered_requests {
   190	        if permission_requests.contains(request.request_id.as_str()) {
   191	            continue;
   192	        }
   193	        let state = match request.state {
   194	            RequestSnapshotState::Queued | RequestSnapshotState::Running => {
   195	                IslandAttentionState::Running
   196	            }
   197	            RequestSnapshotState::WaitingForPermission => IslandAttentionState::NeedsHuman,
   198	            RequestSnapshotState::Cancelling => IslandAttentionState::Cancelling,
   199	            RequestSnapshotState::Errored if failed_count < 3 => {
   200	                failed_count += 1;
   201	                IslandAttentionState::Failed
   202	            }
   203	            RequestSnapshotState::Errored
   204	            | RequestSnapshotState::Cancelled
   205	            | RequestSnapshotState::Completed => continue,
   206	        };
   207	        let (session_title, project) =
   208	            session_attention_metadata(sessions, request.session_id.as_deref());
   209	        let detail = request
   210	            .message
   211	            .as_deref()
   212	            .map(str::trim)
   213	            .filter(|message| !message.is_empty())
   214	            .map(bounded_detail)
   215	            .unwrap_or_else(|| state.label().to_string());
   216	        items.push(IslandAttentionItem {
   217	            id: format!("request:{}", request.request_id),
   218	            request_id: request.request_id.clone(),
   219	            permission_id: request.permission_id.clone(),
   220	            session_id: request.session_id.clone(),
   221	            session_title,
   222	            project,
   223	            tool: None,
   224	            detail,
   225	            updated_at: request_updated_at(request),
   226	            state,
   227	        });
   228	    }
   229	
   230	    items.sort_by(|a, b| {
   231	        a.state
   232	            .rank()
   233	            .cmp(&b.state.rank())
   234	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   235	            .then_with(|| a.id.cmp(&b.id))
   236	    });
   237	    items
   238	}
