   509	    let selected_index = RwSignal::new(0usize);
   510	    let previous_mode = RwSignal::new(IslandMode::Closed);
   511	    let previous_focus = StoredValue::new_local(None::<web_sys::HtmlElement>);
   512	    let last_focus_request = RwSignal::new(0u64);
   513	    let recency_tick = RwSignal::new(0u64);
   514	    let expanded_attention = RwSignal::new(None::<String>);
   515	    let input_ref: NodeRef<leptos::html::Input> = NodeRef::new();
   516	    let chip_ref: NodeRef<leptos::html::Button> = NodeRef::new();
   517	    let popover_ref: NodeRef<leptos::html::Section> = NodeRef::new();
   518	
   519	    #[cfg(target_arch = "wasm32")]
   520	    let recency_interval =
   521	        send_wrapper::SendWrapper::new(gloo_timers::callback::Interval::new(60_000, move || {
   522	            recency_tick.update(|tick| *tick = tick.wrapping_add(1))
   523	        }));
   524	    #[cfg(target_arch = "wasm32")]
   525	    on_cleanup(move || drop(recency_interval));
   526	
   527	    #[cfg(target_arch = "wasm32")]
