   538	    let request_list = daemon.request_list;
   539	    let permission_list = daemon.permission_list;
   540	    let pending_permissions = daemon.pending_permissions;
   541	    let active_decision_token = daemon.active_decision_token;
   542	    let request_cancellations = daemon.request_cancellations;
   543	    let projects = daemon.projects;
   544	    let focused_id = daemon.session_id;
   545	    let daemon = StoredValue::new(daemon);
