   672	    let on_keydown = move |event: KeyboardEvent| {
   673	        if mode.get_untracked() == IslandMode::Closed || event.is_composing() {
   674	            return;
   675	        }
   676	        let key = event.key();
   677	        if key == "Escape" {
   678	            event.prevent_default();
   679	            event.stop_propagation();
   680	            close();
   681	            return;
   682	        }
   683	        if key == "Tab" {
   684	            // Phase 2 adds real disclosure/action controls. Keep them inside the
   685	            // modal focus loop while leaving session rows on the combobox's
   686	            // active-descendant path.
   687	            event.prevent_default();
