   689	            if let Some(popover) = popover_ref.get() {
   690	                if let Ok(nodes) = popover.query_selector_all(
   691	                    ".island-search__input, .island-attention__summary, .island-attention__deny:not([disabled]), .island-attention__approve:not([disabled]), .island-attention__stop:not([disabled]), .island-attention__open:not([disabled])",
   692	                ) {
   693	                    for index in 0..nodes.length() {
   694	                        if let Some(element) = nodes
   695	                            .item(index)
   696	                            .and_then(|node| node.dyn_into::<web_sys::HtmlElement>().ok())
   697	                        {
   698	                            focusable.push(element);
   699	                        }
   700	                    }
   701	                }
   702	            }
   703	            if focusable.is_empty() {
   704	                if let Some(input) = input_ref.get() {
   705	                    let _ = input.focus();
   706	                }
   707	                return;
   708	            }
   709	            let current = event
   710	                .target()
   711	                .and_then(|target| target.dyn_into::<web_sys::Node>().ok());
   712	            let current_index = focusable
   713	                .iter()
   714	                .position(|element| {
   715	                    element
   716	                        .clone()
   717	                        .unchecked_into::<web_sys::Node>()
   718	                        .is_same_node(current.as_ref())
   719	                })
   720	                .unwrap_or(0);

