   318	/// Project daemon sessions into the compact metadata used by the Island.
   319	pub(crate) fn derive_island_sessions(
   320	    sessions: &[SessionSummary],
   321	    projects: &[ProjectInfo],
   322	    focused_id: Option<&str>,
   323	) -> Vec<IslandSession> {
   324	    let mut items: Vec<_> = sessions
   325	        .iter()
   326	        .map(|session| {
   327	            let root = session_root(session).to_string();
   328	            let project = session
   329	                .owning_project
   330	                .as_ref()
   331	                .map(|owner| {
   332	                    if owner.name.trim().is_empty() {
   333	                        owner.id.clone()
   334	                    } else {
   335	                        owner.name.trim().to_string()
   336	                    }
   337	                })
   338	                .or_else(|| {
   339	                    project_for_root(projects, &root).map(|project| {
   340	                        if project.name.trim().is_empty() {
   341	                            project.id.clone()
   342	                        } else {
   343	                            project.name.trim().to_string()
   344	                        }
   345	                    })
   346	                });
   347	            let (origin, clean_title) = split_origin(&session.title);
   348	            let title = if clean_title.trim().is_empty() {
   349	                "(untitled)".to_string()
   350	            } else {
   351	                clean_title
   352	            };
   353	            let is_focused = focused_id == Some(session.id.as_str());
   354	            let priority = if is_focused {
   355	                IslandPriority::Focused
   356	            } else if recently_updated(&session.updated_at) {
   357	                IslandPriority::Recent
   358	            } else {
   359	                IslandPriority::Background
   360	            };
   361	
   362	            IslandSession {
   363	                id: session.id.clone(),
   364	                title,
   365	                project,
   366	                cwd: root,
   367	                branch: session.git_branch.clone().filter(|value| !value.is_empty()),
   368	                origin,
   369	                updated_at: session.updated_at.clone(),
   370	                turn_count: session.turn_count,
   371	                is_focused,
   372	                priority,
   373	            }
   374	        })
   375	        .collect();
   376	
   377	    items.sort_by(|a, b| {
   378	        b.is_focused
   379	            .cmp(&a.is_focused)
   380	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   381	            .then_with(|| a.title.to_lowercase().cmp(&b.title.to_lowercase()))
   382	            .then_with(|| a.id.cmp(&b.id))
   383	    });
   384	    items
   385	}
