   387	/// Normalized session document shared by Browse filtering and `Cmd/Ctrl+P`.
   388	pub(crate) fn island_search_text(item: &IslandSession) -> String {
   389	    let state = match item.priority {
   390	        IslandPriority::Focused => "focused",
   391	        IslandPriority::Recent => "recent",
   392	        IslandPriority::Background => "background",
   393	    };
   394	    let project = item.project.as_deref().unwrap_or_default();
   395	    let branch = item.branch.as_deref().unwrap_or_default();
   396	    let origin = item.origin.as_deref().unwrap_or_default();
   397	    format!(
