   404	/// Search the Island corpus while preserving derivation order for an empty
   405	/// query and using focus/recency only as small tie-breaks for real queries.
   406	pub(crate) fn search_island(query: &str, items: &[IslandSession]) -> Vec<IslandResult> {
   407	    let query = query.trim();
   408	    if query.is_empty() {
   409	        return items.iter().cloned().map(IslandResult::Session).collect();
   410	    }
   411	
   412	    let query_lower = query.to_lowercase();
   413	    let mut scored: Vec<(u8, f64, usize, IslandSession)> = items
   414	        .iter()
   415	        .enumerate()
   416	        .filter_map(|(index, item)| {
   417	            let document_score = fuzzy_score(query, &island_search_text(item))?;
   418	            let title = item.title.to_lowercase();
   419	            let title_score = fuzzy_score(query, &item.title);
   420	            let project = item.project.as_deref().map(str::to_lowercase);
   421	            let project_score = project
   422	                .as_deref()
   423	                .and_then(|project| fuzzy_score(query, project));
   424	
   425	            // Match category is a strict tier; fuzzy score only orders items
   426	            // inside a tier, so a long fuzzy title can never outrank an exact
   427	            // project (and metadata can never outrank a title/project match).
   428	            let (tier, mut score) = if title == query_lower {
   429	                (6, title_score.unwrap_or(document_score))
   430	            } else if title.starts_with(&query_lower) {
   431	                (5, title_score.unwrap_or(document_score))
   432	            } else if project.as_deref() == Some(query_lower.as_str()) {
   433	                (4, project_score.unwrap_or(document_score))
   434	            } else if project
   435	                .as_deref()
   436	                .is_some_and(|project| project.starts_with(&query_lower))
   437	            {
   438	                (3, project_score.unwrap_or(document_score))
   439	            } else if let Some(title_score) = title_score {
   440	                (2, title_score)
   441	            } else if let Some(project_score) = project_score {
   442	                (1, project_score)
   443	            } else {
   444	                (0, document_score)
   445	            };
   446	            score += match item.priority {
   447	                IslandPriority::Focused => 2.0,
   448	                IslandPriority::Recent => 1.0,
   449	                IslandPriority::Background => 0.0,
   450	            };
   451	            Some((tier, score, index, item.clone()))
   452	        })
   453	        .collect();
   454	
   455	    scored.sort_by(|a, b| {
   456	        b.0.cmp(&a.0)
   457	            .then_with(|| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal))
   458	            .then_with(|| a.2.cmp(&b.2))
   459	            .then_with(|| a.3.id.cmp(&b.3.id))
   460	    });
   461	    scored
   462	        .into_iter()
   463	        .map(|(_, _, _, item)| IslandResult::Session(item))
   464	        .collect()
   465	}
