   264	fn permission_action_state(
   265	    permission_id: Option<&str>,
   266	    session_id: Option<&str>,
   267	    focused_id: Option<&str>,
   268	    has_decision_token: bool,
   269	    pending: &[PendingPermission],
   270	) -> Option<bool> {
   271	    let permission_id = permission_id?;
   272	    let session_id = session_id?;
   273	    if !has_decision_token || focused_id != Some(session_id) {
   274	        return None;
   275	    }
   276	    pending
   277	        .iter()
   278	        .find(|item| item.permission_id == permission_id && item.session_id == session_id)
   279	        .map(|item| item.deciding)
